import torch
from clharness.train.hooks import BaseHook

class CodeHalfSpace(BaseHook):
    def on_run_start(self, ctx):
        self.weights = [p for p in ctx.model.parameters() if p.requires_grad]
        self.direction = [p.detach().float().clone() for p in self.weights]
        self.active = False

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        if not self.active:
            self.norm = torch.zeros((), device=self.weights[0].device)
            for p, d in zip(self.weights, self.direction):
                d.neg_().add_(p.detach().float())
                self.norm.add_(d.square().sum())
            self.norm.clamp_(min=1e-20)
            self.previous = [p.detach().clone() for p in self.weights]
            self.active = True

    @torch.no_grad()
    def on_step_end(self, ctx, stats):
        if self.active:
            dot = torch.zeros((), device=self.weights[0].device)
            for p, old, d in zip(self.weights, self.previous, self.direction):
                delta = p.detach().float() - old.float()
                dot.add_((delta * d).sum())
            coefficient = (dot / self.norm).clamp(max=0.0)
            for p, old, d in zip(self.weights, self.previous, self.direction):
                p.copy_((p.detach().float() - coefficient * d).to(dtype=p.dtype))
                old.copy_(p)

import torch
from clharness.train.hooks import BaseHook

class CoordinateShield(BaseHook):
    def on_run_start(self, ctx):
        self.weights = [p for p in ctx.model.parameters() if p.requires_grad]
        self.previous = [p.detach().clone() for p in self.weights]
        self.importance = [torch.zeros_like(p, dtype=torch.float32) for p in self.weights]
        self.active = False

    @torch.no_grad()
    def on_step_end(self, ctx, stats):
        if not self.active:
            for p, old, score in zip(self.weights, self.previous, self.importance):
                if p.grad is not None:
                    score.mul_(0.95).add_(p.grad.detach().float().square(), alpha=0.05)
                old.copy_(p)
            return
        raw_norm = torch.zeros((), device=self.weights[0].device)
        filtered_norm = torch.zeros_like(raw_norm)
        for p, old, score in zip(self.weights, self.previous, self.importance):
            delta = p.detach().float() - old.float()
            filtered = delta / (1.0 + 10.0 * score / self.mean_score)
            raw_norm.add_(delta.square().sum())
            filtered_norm.add_(filtered.square().sum())
        scale = (raw_norm / filtered_norm.clamp(min=1e-30)).sqrt()
        for p, old, score in zip(self.weights, self.previous, self.importance):
            delta = p.detach().float() - old.float()
            filtered = delta / (1.0 + 10.0 * score / self.mean_score)
            p.copy_((old.float() + scale * filtered).to(dtype=p.dtype))
            old.copy_(p)

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        if not self.active:
            total = torch.zeros((), device=self.weights[0].device)
            count = 0
            for p, old, score in zip(self.weights, self.previous, self.importance):
                total.add_(score.sum())
                count += score.numel()
                old.copy_(p)
            self.mean_score = (total / max(count, 1)).clamp(min=1e-30)
            self.active = True
